import crypto from 'node:crypto';
import { Pool } from 'pg';

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

interface IncomingLead {
  tenantId: string;
  portChannel: 'META_FORM' | 'WEB_3D' | 'ZALO_OA' | 'TIKTOK' | 'QR_OOH';
  phoneNormalized: string;
  email?: string;
  fbclid?: string;
  eventId: string;
}

export async function dispatchLeadRoundRobin(lead: IncomingLead) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    await client.query(`SET LOCAL app.current_tenant_id = $1`, [lead.tenantId]);

    // 1. Loc trung 180 ngay (6 thang): neu da co Sale cham thi gan thang cho Sale do
    const dupRes = await client.query(
      `SELECT assigned_rep_id, id FROM crm_leads
       WHERE phone_normalized = $1 AND created_at >= NOW() - INTERVAL '180 days'
       ORDER BY created_at DESC LIMIT 1`,
      [lead.phoneNormalized]
    );
    if (dupRes.rowCount && dupRes.rows[0].assigned_rep_id) {
      await client.query('COMMIT');
      return { status: 'DEDUP_ROUTED', repId: dupRes.rows[0].assigned_rep_id };
    }

    // 2. Khoa dong nguyen tu bang FOR UPDATE SKIP LOCKED chong tranh chap giua 5 cong
    // Uu tien Sale co diem bu ticket (compensation_credits > 0) roi moi quay vong last_assigned_at
    const repRes = await client.query(
      `SELECT id, zalo_user_id, compensation_credits
       FROM sales_routing_roster
       WHERE tenant_id = $1 AND is_online = true AND active_port = $2
       ORDER BY (compensation_credits > 0) DESC, last_assigned_at ASC NULLS FIRST
       LIMIT 1
       FOR UPDATE SKIP LOCKED`,
      [lead.tenantId, lead.portChannel]
    );
    if (!repRes.rowCount) throw new Error('No online rep available for Round-Robin port');

    const rep = repRes.rows[0];
    await client.query(
      `UPDATE sales_routing_roster
       SET last_assigned_at = NOW(),
           compensation_credits = GREATEST(0, compensation_credits - 1)
       WHERE id = $1`,
      [rep.id]
    );

    await client.query(
      `INSERT INTO crm_leads (tenant_id, phone_normalized, assigned_rep_id, stage_code, sla_deadline_at)
       VALUES ($1, $2, $3, 'NEW_ASSIGNED', NOW() + INTERVAL '5 minutes')`,
      [lead.tenantId, lead.phoneNormalized, rep.id]
    );
    await client.query('COMMIT');

    // 3. Neu khách dat lich hen thanh cong, goi Meta CAPI su kien Schedule/Booked voi SHA-256
    const hashedPhone = crypto.createHash('sha256').update(lead.phoneNormalized).digest('hex');
    return { status: 'ASSIGNED_VIA_ZALOBOT', repId: rep.id, hashedPhone };
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}
